A1, A2, AP = 0.25, 0.05, 0.002
def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float)
    n, p = X.shape; ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    S = np.ones((n, 1))
    if len(labs) > 1:
        st = np.array(feats.stratum)
        S = np.column_stack([np.ones(n)] + [(st == l).astype(float) for l in labs[1:]])

    def ll(Z):
        b = np.zeros(Z.shape[1])
        for _ in range(30):
            eta = np.clip(Z @ b, -30, 30); mu = 1 / (1 + np.exp(-eta))
            w = mu * (1 - mu) + 1e-9
            H = Z.T @ (Z * w[:, None]) + 1e-6 * np.eye(Z.shape[1])
            step = np.linalg.solve(H, Z.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(Z @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))

    def mat(cols, extra=()):
        return np.column_stack([S] + [X[:, j] for j in cols] + list(extra))

    def pval(l1, l0, df=1):
        return float(stats.chi2.sf(max(2 * (l1 - l0), 0), df))

    R = np.corrcoef(X.T)
    sel = []; base = ll(mat(sel))
    for k in range(4):
        alpha = (A1 if k == 0 else A2) / p
        best = None
        for j in range(p):
            if j in sel or any(abs(R[j, s]) >= 0.6 for s in sel): continue
            l1 = ll(mat(sel + [j])); pv = pval(l1, base)
            if best is None or pv < best[0]: best = (pv, j, l1)
        if best is None or best[0] > alpha: break
        sel.append(best[1]); base = best[2]
    changed = True
    while changed and len(sel) > 1:
        changed = False
        full = ll(mat(sel))
        pvs = [pval(full, ll(mat([s for s in sel if s != j]))) for j in sel]
        w = int(np.argmax(pvs))
        if pvs[w] > 0.05 / p: sel.pop(w); changed = True

    prods = []; npair = p * (p + 1) / 2
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6: continue
            mains = sorted(set(sel) | {a, b})
            l0 = ll(mat(mains)); l1 = ll(mat(mains, [X[:, a] * X[:, b]]))
            pv = pval(l1, l0)
            if pv < AP / npair: prods.append((pv, a, b))
    prods = sorted(prods)[:2]
    if prods:
        keep = set(j for _, a, b in prods for j in (a, b))
        pe = [X[:, a] * X[:, b] for _, a, b in prods]
        full = ll(mat(sorted(set(sel) | keep), pe))
        sel = [s for s in sel if s in keep or
               pval(full, ll(mat(sorted((set(sel) | keep) - {s}), pe))) < 0.05 / p]
    drivers = []
    for _, a, b in prods:
        for j in (a, b):
            if ids[j] not in drivers: drivers.append(ids[j])
    for j in sel:
        if ids[j] not in drivers: drivers.append(ids[j])
    cols = sorted(set(sel) | set(j for _, a, b in prods for j in (a, b)))
    return Design(drivers=tuple(drivers[:MAX_DRIVERS]), columns=tuple(ids[j] for j in cols),
                  products=tuple((ids[a], ids[b]) for _, a, b in prods), loadings={})

